import { useId } from 'react';

/* ============================================================================
 * LOGO — Ask Analyst
 * ============================================================================
 * Generated from the brand SVGs, so the path data is exact rather than retyped.
 *
 * ONE component covers both colour schemes. The supplied Default and Dark files
 * differ ONLY in the ten wordmark paths (#1F2630 vs white) — the mark itself is
 * byte-identical apart from sub-pixel rounding. Shipping two files would mean
 * two things to keep in sync for no benefit, so the wordmark uses currentColor
 * and takes its colour from the --ask-logo-wordmark token.
 *
 * BRAND COLOURS ARE NOT THE UI TOKEN. The mark uses #0EA4F1 -> #0077CA
 * (gradient), #0086DB and #09A2F0 — none of which is the interface brand blue
 * #1485ff. These are left EXACTLY as supplied: a logo is a fixed asset and must
 * not be recoloured to match the interface.
 *
 * The gradient id is generated per instance with useId — a hard-coded id
 * collides when two logos render on one page, and the second one loses its fill.
 * ========================================================================= */

export interface LogoProps {
  /** Rendered height in px; width scales with the aspect ratio. */
  height?: number;
  /**
   * Accessible name. Pass `null` when the logo sits beside a text version of
   * the same name, so screen readers do not announce it twice.
   */
  title?: string | null;
  className?: string;
}

